// Some portions generated by Claude

// Plan task M7.1: the route lifecycle contract (workbench.routes) and how bootstrap mounts and disposes a route.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { FakeWindow } = require('./browser-fakes.js');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');

const scripts = process.env.WORKBENCH_SCRIPT_DIR
    || path.resolve(__dirname, '../../tools/workbench/src/main/webapp/scripts');

function loadWorkbench(window = {}) {
    const workbench = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ console, URL, URLSearchParams, Promise, window, workbench, setTimeout });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        const absolutePath = path.join(scripts, filename);
        vm.runInContext(fs.readFileSync(absolutePath, 'utf8'), context, { filename: absolutePath });
    }
    window.workbench = context.workbench;
    return context.workbench;
}

function fakeRuntime() {
    return {
        nothing: '',
        html(strings, ...values) { return { strings: Array.from(strings), values }; },
        render(template, mount) { mount.template = template; }
    };
}

function pageResponse(events) {
    return { ok: true, records: events };
}

/** An in-memory stand-in for the worker-backed row store and the NDJSON reader. */
function installTestStream(workbench) {
    workbench.queryStream = {
        async recoverPendingRowStores() {},
        markCurrentRowStoresForRecovery() {},
        async createRowStore() {
            const rows = [];
            return {
                async append(batch) { rows.push(...batch); return rows.length; },
                async read(start, count) { return rows.slice(start, start + count); },
                async count() { return rows.length; },
                async dispose() {}
            };
        },
        async consumeNdjsonResponse(response, options) {
            for (const record of response.records) {
                await options.onRecord(record);
            }
            return { type: 'end' };
        }
    };
}

/** A page document and window just large enough for bootstrap to render a route. */
function page(viewId) {
    const window = new FakeWindow('page', `https://example.test/workbench/repositories/repo-1/${viewId}`);
    const document = {
        location: window.location,
        body: { classList: { add() {} } },
        documentElement: { setAttribute() {} },
        readyState: 'complete',
        getElementById() { return null; }
    };
    window.document = document;
    window.localStorage = { getItem() { return null; }, setItem() {} };
    window.matchMedia = () => ({ matches: false });
    const mount = {
        ownerDocument: document,
        getAttribute(name) {
            return {
                'data-workbench-fetch-page-model': 'true',
                'data-workbench-view': viewId,
                'data-workbench-base-path': '/workbench',
                'data-workbench-repository-id': 'repo-1'
            }[name] || null;
        }
    };
    const events = [
        { type: 'head', version: 1 },
        { type: 'view', id: viewId },
        { type: 'vars', values: ['context'] },
        { type: 'rows', values: [[{ kind: 'iri', value: 'urn:graph' }]] },
        { type: 'end' }
    ];
    return { window, mount, dependencies: { fetch: () => Promise.resolve(pageResponse(events)), runtime: fakeRuntime(), skipScripts: true } };
}

test('registering a definition makes its route known and router-ready', () => {
    const workbench = loadWorkbench();
    const definition = { viewId: 'example', routerReady: true, scripts: () => [], baseScripts: () => [], mount() {} };

    assert.equal(workbench.routes.get('example'), undefined);
    assert.equal(workbench.routes.isRouterReady('example'), false);
    workbench.routes.register(definition);
    assert.equal(workbench.routes.get('example'), definition);
    assert.equal(workbench.routes.isRouterReady('example'), true);
    workbench.routes.register({ ...definition, routerReady: false });
    assert.equal(workbench.routes.isRouterReady('example'), false);
});

test('the route registry loads on its own, before any other Workbench script', () => {
    const absolutePath = path.join(scripts, 'workbenchRoutes.js');
    const context = vm.createContext({ Promise });
    vm.runInContext(fs.readFileSync(absolutePath, 'utf8'), context, { filename: absolutePath });

    assert.equal(context.workbench.routes.get('summary').viewId, 'summary');
});

test('the built-in definitions carry the script lists the pages load today', () => {
    const workbench = loadWorkbench();
    const routes = workbench.routes;
    assert.deepEqual(Array.from(routes.get('query').scripts({ vars: [] })), ['queryStream.js', 'codemirror.4.5.0.min.js',
        'yasqe.min.js', 'yasqeHelper.js', 'queryCancelPolicy.js', 'diff.min.js', 'viz/viz.js', 'viz/full.render.js',
        'svg-pan-zoom.min.js', 'queryExplanationHighlighter.js', 'paging.js', 'query.js']);
    assert.deepEqual(Array.from(routes.get('explore').baseScripts()), ['paging.js', 'explore.js']);
    assert.deepEqual(Array.from(routes.get('contexts').scripts({ vars: ['context'] })), []);
    assert.deepEqual(Array.from(routes.get('create').baseScripts()), ['create.js']);
    assert.deepEqual(Array.from(routes.get('create').scripts({ vars: ['type', 'label'] })), []);
    assert.deepEqual(Array.from(routes.get('create').scripts({ vars: ['fieldId', 'label'] })), ['create.js']);
    assert.deepEqual(Array.from(routes.get('create').scripts({ vars: ['id', 'description', 'location'] })),
        ['create.js', 'create-federate.js']);
    assert.deepEqual(Array.from(routes.get('create').scripts({ vars: ['location'] })), []);
    assert.deepEqual(Array.from(routes.get('create').scripts({ vars: ['description', 'location'] })), []);
    for (const viewId of ['summary', 'information', 'repositories', 'delete', 'namespaces', 'contexts', 'types', 'explore',
        'query', 'saved-queries', 'export', 'add', 'remove', 'clear', 'update', 'server', 'create']) {
        assert.equal(routes.get(viewId).viewId, viewId);
        assert.equal(routes.isRouterReady(viewId), false, viewId + ' is not converted yet');
    }
});

test('bootstrap mounts a registered route once and disposes it once on a real pagehide', async () => {
    const { window, mount, dependencies } = page('contexts');
    const workbench = loadWorkbench(window);
    installTestStream(workbench);
    workbench.views.render = () => ({ status: 'rendered' });
    const contexts = [];
    const disposals = [];
    workbench.routes.register({
        viewId: 'contexts', routerReady: true, scripts: () => [], baseScripts: () => [],
        mount(ctx) {
            contexts.push(ctx);
            return { dispose: (reason) => disposals.push(reason) };
        }
    });

    const result = await workbench.app.bootstrap(mount, dependencies);

    assert.equal(result.status, 'rendered');
    assert.equal(contexts.length, 1, 'the route is mounted once');
    assert.equal(contexts[0].model.viewId, 'contexts');
    assert.equal(contexts[0].context.repositoryId, 'repo-1');
    assert.equal(String(contexts[0].url), 'https://example.test/workbench/repositories/repo-1/contexts');
    assert.equal(window.listenerCount('pagehide'), 1);
    window.dispatchEvent({ type: 'pagehide', persisted: true });
    assert.deepEqual(disposals, [], 'a page kept in the back/forward cache stays mounted');
    window.dispatchEvent({ type: 'pagehide', persisted: false });
    window.dispatchEvent({ type: 'pagehide', persisted: false });
    assert.deepEqual(disposals, ['pagehide'], 'a page that is left is disposed exactly once');
    assert.equal(window.listenerCount('pagehide'), 0);
});

test('the default mount releases the row windows and the row store exactly once', async () => {
    const workbench = loadWorkbench();
    const released = [];
    let resolveBinding;
    workbench.views.bindRowWindows = () => new Promise((resolve) => { resolveBinding = resolve; });
    workbench.views.renderOutlet = () => released.push('render');
    const model = { rowStore: { dispose: () => released.push('row-store') } };
    const ctx = { outlet: {}, model, context: {}, runtime: fakeRuntime(), url: new URL('https://example.test/'),
        state: { rendered: true } };

    const instance = workbench.routes.defaultMount(ctx);
    resolveBinding(() => released.push('row-windows'));
    await instance.ready;
    instance.dispose('navigate');
    instance.dispose('pagehide');
    assert.deepEqual(released, ['row-windows', 'row-store'], 'the first page load is not rendered again');

    released.length = 0;
    const early = workbench.routes.defaultMount({ ...ctx, state: undefined });
    early.dispose('navigate');
    resolveBinding(() => released.push('row-windows'));
    await early.ready;
    assert.deepEqual(released, ['render', 'row-store', 'row-windows'],
        'a route disposed before its rows were bound still releases them once they are');

    released.length = 0;
    workbench.views.bindRowWindows = undefined;
    const bare = workbench.routes.defaultMount({ ...ctx, model: {} });
    await bare.ready;
    bare.dispose('navigate');
    assert.deepEqual(released, [], 'a page without row windows or a row store has nothing to release');
});
